package com.cayadev.orbo.games

import android.graphics.Canvas
import com.cayadev.orbo.data.Category
import com.cayadev.orbo.data.GameMeta
import com.cayadev.orbo.data.IconDrawer
import com.cayadev.orbo.data.Tier
import com.cayadev.orbo.engine.Draw
import com.cayadev.orbo.engine.Fonts
import com.cayadev.orbo.engine.Mathx
import com.cayadev.orbo.engine.Palette
import com.cayadev.orbo.engine.ScreenInfo
import com.cayadev.orbo.game.ArcadeGame

/**
 * Lights Out — flip every light off. Tapping a cell toggles it and its four neighbours. Boards are
 * generated by scrambling a solved grid, so every puzzle is guaranteed solvable. Clear as many as
 * you can before the 90-second clock runs out.
 */
class LightsOutGame : ArcadeGame(meta()) {

    private val sz = 5
    private val n = sz * sz
    private val on = BooleanArray(n)
    private val fx = FloatArray(n)
    private var boards = 0
    private var moves = 0
    private var timeLeft = 90f

    override val controlHint = "TAP TO TOGGLE LIGHTS"
    override val gameOverTitle = "TIME UP"

    override fun onReset() { boards = 0; moves = 0; timeLeft = 90f; newBoard() }

    private fun applyToggle(idx: Int) {
        val r = idx / sz; val col = idx % sz
        on[idx] = !on[idx]
        if (r > 0) on[idx - sz] = !on[idx - sz]
        if (r < sz - 1) on[idx + sz] = !on[idx + sz]
        if (col > 0) on[idx - 1] = !on[idx - 1]
        if (col < sz - 1) on[idx + 1] = !on[idx + 1]
    }

    private fun newBoard() {
        for (i in 0 until n) { on[i] = false; fx[i] = 0f }
        val scramble = (3 + boards).coerceAtMost(9)
        repeat(scramble) { applyToggle(Mathx.rand(n)) }
        if ((0 until n).all { !on[it] }) applyToggle(Mathx.rand(n))  // never start solved
        moves = 0
    }

    private fun boardSide(s: ScreenInfo) = if (s.isRound) s.minDim * 0.66f else s.minDim * 0.82f
    private fun boardTop(s: ScreenInfo) = s.h * 0.55f - boardSide(s) / 2f
    private fun cell(s: ScreenInfo) = boardSide(s) / sz

    override fun onStep(dt: Float) {
        timeLeft -= dt
        for (i in 0 until n) if (fx[i] > 0f) fx[i] -= dt
        if (timeLeft <= 0f) { timeLeft = 0f; gameOver() }
    }

    override fun onTapWorld(x: Float, y: Float) {
        val s = sc; val cs = cell(s); val x0 = s.cx - boardSide(s) / 2f; val y0 = boardTop(s)
        val col = ((x - x0) / cs).toInt(); val row = ((y - y0) / cs).toInt()
        if (col !in 0 until sz || row !in 0 until sz) return
        val idx = row * sz + col
        applyToggle(idx); moves++
        engine.sfx.click(); engine.haptics.light()
        fx[idx] = 0.25f
        if ((0 until n).all { !on[it] }) {
            boards++
            val bonus = (260 - moves * 8).coerceAtLeast(60)
            addScore(bonus); timeLeft += 6f
            engine.sfx.success(); engine.haptics.success(); flash(accent, 0.25f)
            newBoard()
        }
    }

    override fun onDraw(c: Canvas, s: ScreenInfo) {
        Draw.background(c, Palette.bg)
        Draw.vignette(c, s, Palette.bgSoft, Palette.bg)
        if (state == GState.READY) return
        val cs = cell(s); val x0 = s.cx - boardSide(s) / 2f; val y0 = boardTop(s)
        val pad = cs * 0.11f
        for (i in 0 until n) {
            val col = i % sz; val row = i / sz
            val cx = x0 + col * cs + cs / 2; val cy = y0 + row * cs + cs / 2
            val side = cs - pad * 2
            val pop = 1f + 0.10f * fx[i].coerceIn(0f, 1f)
            if (on[i]) {
                Draw.glow(c, cx, cy, side * 0.8f, accent, 0.35f)
                Draw.roundRectCentered(c, cx, cy, side * pop, side * pop, side * 0.24f, Palette.alpha(accent, 0.92f))
                Draw.roundRectStroke(c, cx - side / 2, cy - side / 2, side, side, side * 0.24f, Palette.alpha(Palette.text, 0.25f), s.dp(1.4f))
            } else {
                Draw.roundRectCentered(c, cx, cy, side, side, side * 0.24f, Palette.panel)
                Draw.roundRectStroke(c, cx - side / 2, cy - side / 2, side, side, side * 0.24f, Palette.alpha(accent, 0.16f), s.dp(1.2f))
            }
        }
    }

    override fun onDrawHud(c: Canvas, s: ScreenInfo) {
        if (state != GState.PLAYING) return
        val barW = s.px(0.4f); val frac = (timeLeft / 90f).coerceIn(0f, 1f)
        Draw.roundRect(c, s.cx - barW / 2, s.h * 0.20f, barW, s.dp(5f), s.dp(3f), Palette.track)
        Draw.roundRect(c, s.cx - barW / 2, s.h * 0.20f, barW * frac, s.dp(5f), s.dp(3f), Palette.lerp(Palette.red, accent, frac))
    }

    override fun drawScoreHud(c: Canvas, s: ScreenInfo) {
        Draw.textCentered(c, "$score", s.cx, s.h * 0.125f, s.px(0.065f), Palette.text, Fonts.display)
    }

    companion object {
        fun meta() = GameMeta(
            id = "lights_out",
            title = "Lights Out",
            tagline = "Turn them all off",
            category = Category.STRATEGY,
            tier = Tier.MINI,
            accent = Palette.lime,
            icon = IconDrawer { c, cx, cy, size, color ->
                val u = size * 0.30f
                for (r in -1..1) for (cc in -1..1) {
                    val onCell = (r + cc) % 2 == 0
                    Draw.roundRectCentered(c, cx + cc * u, cy + r * u, u * 0.82f, u * 0.82f, u * 0.2f,
                        if (onCell) color else Palette.alpha(color, 0.2f))
                }
            },
            create = { LightsOutGame() }
        )
    }
}
